B06.final_patch:
def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value

B07.final_patch:
def largest(numbers):
    best = numbers[0]
    for n in numbers:
        if n > best:
            best = n
    return best

